from django.db import migrations

from vitrina.structure import VersionStatus


def assign_version_number_if_missing(apps, schema_editor):
    Version = apps.get_model("vitrina_structure", "Version")

    datasets_with_no_versions = Version.objects.filter(
        version__isnull=True
    ).values_list("dataset_id", flat=True).distinct()

    versions_to_update = []

    for dataset_id in datasets_with_no_versions:
        all_dataset_versions = list(
            Version.objects.filter(dataset_id=dataset_id).order_by("created")
        )

        for version_number, version_obj in enumerate(all_dataset_versions, start=1):
            version_obj.version = version_number
            versions_to_update.append(version_obj)

    if versions_to_update:
        Version.objects.bulk_update(versions_to_update, fields=["version"])


def create_version_for_datasets_with_no_version(apps, schema_editor):
    Dataset = apps.get_model('vitrina_datasets', 'Dataset')
    Version = apps.get_model('vitrina_structure', 'Version')

    for dataset in Dataset.objects.filter(dataset_version__isnull=True).prefetch_related("metadata_set"):
        created_draft_version = Version.objects.create(dataset=dataset, version=1, status=VersionStatus.DRAFT)
        for metadata in dataset.metadata_set.all():
            metadata.metadata_version = created_draft_version
            metadata.save()


